catalog_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
	g_form.clearOptions('report_submission');
   if (g_lang == "en"){
		g_form.addOption('report_submission', '', 'Please select..');
		g_form.addOption('report_submission', 'submit', 'Submit the report');
		g_form.addOption('report_submission', 'draft', 'Save as a draft');
   }
	else
	{
		g_form.addOption('report_submission', '', 'Veuillez sélectionner..');
		g_form.addOption('report_submission', 'submit', 'Soumettre le rapport');
		g_form.addOption('report_submission', 'draft', 'Enregistrer comme brouillon');
	}
}
